def get_web_url(container_key, ip_address):
    """Generate web URL for a container given its key and IP address."""
    config = WEB_URL_CONFIGS.get(container_key)
    if not config:
        # Try to get from container definition ports
        container = CONTAINER_DEFINITIONS.get(container_key)
        if container and container.get('ports'):
            port = container['ports'][0]
            return f"http://{ip_address}:{port}"
        return None
    protocol = config.get('protocol', 'http')
    port = config.get('port', 80)
    path = config.get('path', '')
    return f"{protocol}://{ip_address}:{port}{path}"
