def get_containers_by_category():
    """Group containers by category."""
    grouped = {}
    for key, container in CONTAINER_DEFINITIONS.items():
        category = container['category']
        if category not in grouped:
            grouped[category] = []
        grouped[category].append({**container, 'key': key})
    return grouped
def get_container(key):
    """Get a specific container definition."""
    return CONTAINER_DEFINITIONS.get(key)
def get_all_containers():
    """Get all container definitions with keys."""
    return [{**v, 'key': k} for k, v in CONTAINER_DEFINITIONS.items()]
def get_vms_by_category():
    """Group VMs by category."""
    grouped = {}
    for key, vm in VM_DEFINITIONS.items():
        category = vm['category']
        if category not in grouped:
            grouped[category] = []
        grouped[category].append({**vm, 'key': key, 'type': 'vm'})
    return grouped
def get_vm(key):
    """Get a specific VM definition."""
    return VM_DEFINITIONS.get(key)
def get_all_vms():
    """Get all VM definitions with keys."""
    return [{**v, 'key': k, 'type': 'vm'} for k, v in VM_DEFINITIONS.items()]
def get_all_deployables():
    """Get all containers and VMs combined."""
    containers = [{**v, 'key': k, 'type': 'container'} for k, v in CONTAINER_DEFINITIONS.items()]
    vms = [{**v, 'key': k, 'type': 'vm'} for k, v in VM_DEFINITIONS.items()]
    return containers + vms
def get_deployables_by_category():
    """Group all containers and VMs by category."""
    grouped = {}
    # Add containers
    for key, item in CONTAINER_DEFINITIONS.items():
        category = item['category']
        if category not in grouped:
            grouped[category] = []
        grouped[category].append({**item, 'key': key, 'type': 'container'})
    # Add VMs
    for key, item in VM_DEFINITIONS.items():
        category = item['category']
        if category not in grouped:
            grouped[category] = []
        grouped[category].append({**item, 'key': key, 'type': 'vm'})
    return grouped
